	char	szPassword[SAFEBOX_PASSWORD_MAX_LEN + 1];
	// MT2009_PLUS_MALL_PAGES_V1 (packet) (server-patches/mall3): HEADER_GD_MALL_LOAD only -
	// how many pages of the item-shop storage the player's client shows (1 = an old
	// client, 3 = SAFEBOX_PAGE_COUNT); item_award deliveries fill that many pages.
	// HEADER_GD_SAFEBOX_LOAD leaves it unread.
	BYTE	bMallPages;
} TSafeboxLoadPacket;

// MT2009_PLUS_MALL_PAGES_V1 (command) (server-patches/mall3): a client with the paged
// item-shop storage window sends "/mall_password <password> 3"; an old one sends no
// second word and shows only the first page, so its deliveries stay there.
{
	char szPassword[256], szPages[256];
	two_arguments(argument, szPassword, sizeof(szPassword), szPages, sizeof(szPages));
	int iPages = 1;
	if (*szPages)
		str_to_number(iPages, szPages);
	p.bMallPages = (BYTE) MINMAX(1, iPages, (int) SAFEBOX_PAGE_COUNT);
}

db_clientdesc->DBPacket(HEADER_GD_MALL_LOAD, ch->GetDesc()->GetHandle(), &p, sizeof(p));

pi->ip[0] = bMall ? 1 : 0;
// MT2009_PLUS_MALL_PAGES_V1 (load) (server-patches/mall3): the pages of the item-shop
// storage the client shows, for the item_award grid below (ip[1] is free here).
pi->ip[1] = bMall ? (char) MINMAX(1, (int) packet->bMallPages, (int) SAFEBOX_PAGE_COUNT) : 0;

// MT2009_PLUS_MALL_PAGES_V1 (grid) (server-patches/mall3): the item-shop storage's
// deliveries fill every page the player's client shows (1 or 3); its bSize is
// 1 (or 0 with no safebox row) and was the only limit before.
CGrid grid(5, MAX(1, pi->ip[0] == 1 ? (int) pi->ip[1] : (int) pi->pSafebox->bSize) * 9);
